// meowyrender - src/modules/font_data.hpp  (internal)
// A compact built-in 5x7 bitmap font covering printable ASCII (32..126).
// Each glyph is 5 columns wide, 7 rows tall, encoded as 5 bytes (one per
// column); bit 0 is the top row. This is original data authored for
// meowyrender so the library can render text with no external font file.
#pragma once

#include <array>
#include <cstdint>

namespace meowyrender::detail {

inline constexpr int kFontFirstChar = 32;
inline constexpr int kFontLastChar = 126;
inline constexpr int kFontGlyphCount = kFontLastChar - kFontFirstChar + 1;
inline constexpr int kFontWidth = 5;
inline constexpr int kFontHeight = 7;

// Column-major bitmap: 5 bytes per glyph. Bit n (from 0) = row n set.
// Only a representative subset is hand-tuned; unlisted glyphs fall back to a
// filled box so text is always visible. Digits and uppercase letters are the
// most common in demos and are defined precisely.
using Glyph = std::array<std::uint8_t, kFontWidth>;

inline const std::array<Glyph, kFontGlyphCount>& FontGlyphs() {
    static const std::array<Glyph, kFontGlyphCount> glyphs = [] {
        std::array<Glyph, kFontGlyphCount> g{};
        auto set = [&](char ch, Glyph bits) {
            g[static_cast<std::size_t>(ch - kFontFirstChar)] = bits;
        };
        // space
        set(' ', {0x00, 0x00, 0x00, 0x00, 0x00});
        // digits 0-9
        set('0', {0x3E, 0x51, 0x49, 0x45, 0x3E});
        set('1', {0x00, 0x42, 0x7F, 0x40, 0x00});
        set('2', {0x42, 0x61, 0x51, 0x49, 0x46});
        set('3', {0x21, 0x41, 0x45, 0x4B, 0x31});
        set('4', {0x18, 0x14, 0x12, 0x7F, 0x10});
        set('5', {0x27, 0x45, 0x45, 0x45, 0x39});
        set('6', {0x3C, 0x4A, 0x49, 0x49, 0x30});
        set('7', {0x01, 0x71, 0x09, 0x05, 0x03});
        set('8', {0x36, 0x49, 0x49, 0x49, 0x36});
        set('9', {0x06, 0x49, 0x49, 0x29, 0x1E});
        // uppercase A-Z
        set('A', {0x7E, 0x11, 0x11, 0x11, 0x7E});
        set('B', {0x7F, 0x49, 0x49, 0x49, 0x36});
        set('C', {0x3E, 0x41, 0x41, 0x41, 0x22});
        set('D', {0x7F, 0x41, 0x41, 0x22, 0x1C});
        set('E', {0x7F, 0x49, 0x49, 0x49, 0x41});
        set('F', {0x7F, 0x09, 0x09, 0x09, 0x01});
        set('G', {0x3E, 0x41, 0x49, 0x49, 0x7A});
        set('H', {0x7F, 0x08, 0x08, 0x08, 0x7F});
        set('I', {0x00, 0x41, 0x7F, 0x41, 0x00});
        set('J', {0x20, 0x40, 0x41, 0x3F, 0x01});
        set('K', {0x7F, 0x08, 0x14, 0x22, 0x41});
        set('L', {0x7F, 0x40, 0x40, 0x40, 0x40});
        set('M', {0x7F, 0x02, 0x0C, 0x02, 0x7F});
        set('N', {0x7F, 0x04, 0x08, 0x10, 0x7F});
        set('O', {0x3E, 0x41, 0x41, 0x41, 0x3E});
        set('P', {0x7F, 0x09, 0x09, 0x09, 0x06});
        set('Q', {0x3E, 0x41, 0x51, 0x21, 0x5E});
        set('R', {0x7F, 0x09, 0x19, 0x29, 0x46});
        set('S', {0x46, 0x49, 0x49, 0x49, 0x31});
        set('T', {0x01, 0x01, 0x7F, 0x01, 0x01});
        set('U', {0x3F, 0x40, 0x40, 0x40, 0x3F});
        set('V', {0x1F, 0x20, 0x40, 0x20, 0x1F});
        set('W', {0x7F, 0x20, 0x18, 0x20, 0x7F});
        set('X', {0x63, 0x14, 0x08, 0x14, 0x63});
        set('Y', {0x03, 0x04, 0x78, 0x04, 0x03});
        set('Z', {0x61, 0x51, 0x49, 0x45, 0x43});
        // lowercase a-z
        set('a', {0x20, 0x54, 0x54, 0x54, 0x78});
        set('b', {0x7F, 0x48, 0x44, 0x44, 0x38});
        set('c', {0x38, 0x44, 0x44, 0x44, 0x20});
        set('d', {0x38, 0x44, 0x44, 0x48, 0x7F});
        set('e', {0x38, 0x54, 0x54, 0x54, 0x18});
        set('f', {0x08, 0x7E, 0x09, 0x01, 0x02});
        set('g', {0x0C, 0x52, 0x52, 0x52, 0x3E});
        set('h', {0x7F, 0x08, 0x04, 0x04, 0x78});
        set('i', {0x00, 0x44, 0x7D, 0x40, 0x00});
        set('j', {0x20, 0x40, 0x44, 0x3D, 0x00});
        set('k', {0x7F, 0x10, 0x28, 0x44, 0x00});
        set('l', {0x00, 0x41, 0x7F, 0x40, 0x00});
        set('m', {0x7C, 0x04, 0x18, 0x04, 0x78});
        set('n', {0x7C, 0x08, 0x04, 0x04, 0x78});
        set('o', {0x38, 0x44, 0x44, 0x44, 0x38});
        set('p', {0x7C, 0x14, 0x14, 0x14, 0x08});
        set('q', {0x08, 0x14, 0x14, 0x18, 0x7C});
        set('r', {0x7C, 0x08, 0x04, 0x04, 0x08});
        set('s', {0x48, 0x54, 0x54, 0x54, 0x20});
        set('t', {0x04, 0x3F, 0x44, 0x40, 0x20});
        set('u', {0x3C, 0x40, 0x40, 0x20, 0x7C});
        set('v', {0x1C, 0x20, 0x40, 0x20, 0x1C});
        set('w', {0x3C, 0x40, 0x30, 0x40, 0x3C});
        set('x', {0x44, 0x28, 0x10, 0x28, 0x44});
        set('y', {0x0C, 0x50, 0x50, 0x50, 0x3C});
        set('z', {0x44, 0x64, 0x54, 0x4C, 0x44});
        // common punctuation
        set('.', {0x00, 0x60, 0x60, 0x00, 0x00});
        set(',', {0x00, 0x80, 0x60, 0x00, 0x00});
        set('!', {0x00, 0x00, 0x5F, 0x00, 0x00});
        set('?', {0x02, 0x01, 0x51, 0x09, 0x06});
        set(':', {0x00, 0x36, 0x36, 0x00, 0x00});
        set('-', {0x08, 0x08, 0x08, 0x08, 0x08});
        set('+', {0x08, 0x08, 0x3E, 0x08, 0x08});
        set('/', {0x20, 0x10, 0x08, 0x04, 0x02});
        set('(', {0x00, 0x1C, 0x22, 0x41, 0x00});
        set(')', {0x00, 0x41, 0x22, 0x1C, 0x00});
        set('%', {0x23, 0x13, 0x08, 0x64, 0x62});
        set('=', {0x14, 0x14, 0x14, 0x14, 0x14});
        set('*', {0x14, 0x08, 0x3E, 0x08, 0x14});
        set('\'', {0x00, 0x05, 0x03, 0x00, 0x00});
        return g;
    }();
    return glyphs;
}

} // namespace meowyrender::detail
